    Args:
        paren_string (str): The input string containing parentheses.
    Returns:
        List[str]: A list of strings containing the separate parentheses groups.
    """
    groups = []
    current_group = ""
    stack = []
    for char in paren_string:
        if char == "(":
            if not stack:
                current_group += char
                stack.append(char)
            else:
                current_group += char
                stack.append(char)
        elif char == ")":
