def max_energy(beads):
    # Create a dynamic programming table to store the maximum energy
    # for each combination of beads
    dp = [[0] * (len(beads) + 1) for _ in range(len(beads) + 1)]

    # Initialize the first row and column of the table
    for i in range(len(beads) + 1):
        dp[i][0] = 0
    for j in range(len(beads) + 1):
        dp[0][j] = 0

    # Fill in the table using the recurrence relation
    for i in range(1, len(beads) + 1):
        for j in range(1, len(beads) + 1):
            if j == i:
                dp[i][j] = beads[j - 1] * beads[j - 1]
            else:
                dp[i][j] = max(dp[i - 1][j - 1], dp[i - 1][j] + beads[j - 1] * beads[i - 1])

    # Find the maximum energy by iterating over the final row of the table
    max_energy = 0
    for i in range(len(beads) + 1):
        max_energy = max(max_energy, dp[-1][i])

    return max_energy

def max_energy(beads):
