    dp = [[0] * len(beads) for _ in range(len(beads))]

    # Fill in the values for the first row
    for i in range(len(beads)):
        dp[0][i] = beads[i]

    # Fill in the values for the first column
    for j in range(1, len(beads)):
        dp[j][0] = beads[j]

    # Fill in the remaining values using dynamic programming
    for i in range(1, len(beads)):
        for j in range(1, len(beads)):
            dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # Return the maximum energy
    return dp[len(beads) - 1][len(beads) - 1]

