    return count_partitions(n-x, k-1, x) + count_partitions(n, k, x+1)

def count_partitions(n: int, k: int, x: int) -> int:
    # Base case: if k == 1, there is only one way to partition the number into 1 part
    if k == 1:
        return 1

    # Initialize a 2D array to store the results
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    # Initialize the first row with 1
    for i in range(k + 1):
        dp[0][i] = 1

    # Fill in the 2D array
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            if i - j >= 0:
                dp[i][j] += dp[i - j][j - 1]
            if j > 1:
                dp[i][j] += dp[i][j - 1]

    return dp[n][k]

