def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # calculate the maximum volume that can be occupied in the box by any subset of the given items
    max_volume = 0
    for i in range(1 << n):
        # for each subset of items, calculate the sum of their volumes
        volume = 0
        for j in range(n):
            if i & (1 << j):
                volume += volumes[j]
        # update the maximum volume if the current subset has a larger volume
        if volume > max_volume:
            max_volume = volume

    # return the difference between the box's total capacity and the maximum occupied volume
    return V - max_volume

