def next_permutation(perm: list) -> bool:
    found_index = -1
    for i in range(len(perm) - 2, -1, -1):
        if perm[i] < perm[i + 1]:
            found_index = i
            break
    if found_index == -1:
        return False
    for i in range(len(perm) - 1, found_index, -1):
        if perm[i] > perm[found_index]:
            perm[found_index], perm[i] = perm[i], perm[found_index]
            break
    perm[found_index+1:] = perm[found_index+1:][::-1]
    return True

def next_permutation(perm: list) -> bool:
    if not perm or len(perm) < 2:
        return False

    i = len(perm) - 2
    while i >= 0 and perm[i] >= perm[i+1]:
        i -= 1

    if i < 0:
        return False

    j = len(perm) - 1
    while j >= 0 and perm[j] <= perm[i]:
        j -= 1

    perm[i], perm[j] = perm[j], perm[i]

    perm[i+1:] = perm[len(perm)-1:i:-1]

    return True

